def _looks_like_smi(token: str) -> bool:
    return any(c.isalpha() for c in token) and "/" not in token and " " not in token


def _identity(c: Candidate) -> tuple:
    """What makes two candidates the same thing.

    SMILES and sequence identify a molecule or a protein, but a domain whose candidates carry
    NEITHER — a material described only by its composition metadata — collapses to one key and
    every distinct candidate but the first is silently discarded. Metadata is the fallback
    identity, not an addition: two molecules with the same SMILES are still one molecule
    however they were annotated.
    """
    if c.smi or c.seq:
        return (c.kind, c.smi, c.seq)
    md = c.metadata or {}
    return (c.kind, None, None, tuple(sorted((k, str(v)) for k, v in md.items())))


def _dedup(cands: List[Candidate]) -> List[Candidate]:
    seen = set()
    out = []
    for c in cands:
        key = _identity(c)
        if key in seen:
            continue
        seen.add(key)
        out.append(c)
    # If we had none with SMILES and some with sequences, keep the sequences
    if not [c for c in out if c.smi] and [c for c in out if c.seq]:
        return out
    return out


# Metadata keys that are a MEASUREMENT of a specific structure, not a property of the lineage.
# A mutated child is a different molecule, so inheriting these makes it report its parent's
# docking result as its own — and the evaluators read metadata before falling back to a
# surrogate, so the stale number wins and is stamped "real".
_MEASUREMENT_KEYS = ("vina_score_kcal", "docking_score", "qed_score", "sa_score")



